   139→    C_KZG_RET ret;
   140→    size_t circulant_domain_size;
   141→
   142→    blst_scalar *scalars = NULL;
   143→    fr_t **coeffs = NULL;
   144→    fr_t *circulant_coeffs = NULL;     /* The vectors c_i */
