   146→    g1_t *v = NULL;
   147→    g1_t *u = NULL;
   148→    limb_t *scratch = NULL;
   149→    bool precompute = s->wbits != 0;
   150→
   151→    /*
   152→     * Note: this constant 2 is not related to LOG_EXPANSION_FACTOR. Instead, it is to produce a
   153→     * circulant matrix of size 2r in FK20, see Section 3 in https://eprint.iacr.org/2023/033.pdf.
   154→     */
   155→    circulant_domain_size = CELLS_PER_BLOB * 2;
   156→
   157→    /* Do allocations */
   158→    ret = new_fr_array(&circulant_coeffs, circulant_domain_size);
   159→    if (ret != C_KZG_OK) goto out;
   160→    ret = new_fr_array(&circulant_coeffs_fft, circulant_domain_size);
   161→    if (ret != C_KZG_OK) goto out;
   162→    ret = new_g1_array(&u, circulant_domain_size);
   163→    if (ret != C_KZG_OK) goto out;
   164→    ret = new_g1_array(&v, circulant_domain_size);
   165→    if (ret != C_KZG_OK) goto out;
   166→
   167→    if (precompute) {
   168→        /* Allocations for fixed-base MSM */
   169→        ret = c_kzg_malloc((void **)&scratch, s->scratch_size);
   170→        if (ret != C_KZG_OK) goto out;
   171→        ret = c_kzg_calloc((void **)&scalars, FIELD_ELEMENTS_PER_CELL, sizeof(blst_scalar));
   172→        if (ret != C_KZG_OK) goto out;
   173→    }
   174→
   175→    /* Allocate 2d array for coefficients by column */
   176→    ret = c_kzg_calloc((void **)&coeffs, circulant_domain_size, sizeof(void *));
   177→    if (ret != C_KZG_OK) goto out;
   178→    for (size_t i = 0; i < circulant_domain_size; i++) {
   179→        ret = new_fr_array(&coeffs[i], FIELD_ELEMENTS_PER_CELL);
   180→        if (ret != C_KZG_OK) goto out;
   181→    }
